+  if (ask === "off") return "";
   var cs = (typeof machine !== "undefined" && machine.coolants) || [];
-  var first = "";
+  var flood = !ask || ask === "flood";
+  var want = flood ? ["flood"] : (ask === "mist" ? ["mist"] : (ask === "air" ? ["air", "air-blast"]
