-    if (!code) continue;
-    if (name === "Flood") return code;
-    if (!first) first = code;
+    var name = coolantName(c);
+    if (want.indexOf(name) >= 0) { if (code) return code; if (flood) named = true; continue; }
+    if (flood && code && !other && COOLANT_KINDS.indexOf(name) < 0) other = code;
