+            let stated = match code {
+                Some(Value::String(s)) => !s.trim().is_empty(),
+                Some(Value::Number(_)) => true,
+                _ => false,
+            };
+            if !stated {
+                out.push(Refusal {
+                    key: format!("coolant {name}"),
+                    rule: "has no M code - enter its code (M7 air or mist, M8 flood) or remove the coolant".to_owned(),
+                });
+            }
+        }
+    }
+    out
+}

